document.querySelectorAll(".tab").forEach(function(e){e.addEventListener("click",function(){document.querySelectorAll(".tab").forEach(function(c){c.classList.remove("active")}),document.querySelectorAll(".panel").forEach(function(c){c.classList.remove("active")}),e.classList.add("active"),document.getElementById(e.dataset.panel).classList.add("active")})}),document.querySelectorAll(".question").forEach(function(e){var c=Number(e.dataset.correct);e.querySelectorAll(".option").forEach(function(s){s.addEventListener("click",function(){e.classList.contains("answered")||(e.classList.add("answered"),e.querySelectorAll(".option").forEach(function(t,l){t.disabled=!0,l===c?t.classList.add("correct"):t===s&&t.classList.add("incorrect")}))})})});
